    TResult? Function(TopicsInitial value)? initial,
    TResult? Function(TopicsLoading value)? loading,
    TResult? Function(TopicsLoaded value)? loaded,
    TResult? Function(QuizzesLoaded value)? quizzesLoaded,
    TResult? Function(SearchResults value)? searchResults,
    TResult? Function(RandomQuizLoaded value)? randomQuizLoaded,
    TResult? Function(CachedQuizzesLoaded value)? cachedQuizzesLoaded,
    TResult? Function(TopicsSuccess value)? success,
    TResult? Function(TopicsError value)? error,
    TResult? Function(TopicsOffline value)? offline,
  }) {
    return offline?.call(this);
  }

  @override
  @optionalTypeArgs
  TResult maybeMap<TResult extends Object?>({
    TResult Function(TopicsInitial value)? initial,
    TResult Function(TopicsLoading value)? loading,
    TResult Function(TopicsLoaded value)? loaded,
    TResult Function(QuizzesLoaded value)? quizzesLoaded,
    TResult Function(SearchResults value)? searchResults,
    TResult Function(RandomQuizLoaded value)? randomQuizLoaded,
    TResult Function(CachedQuizzesLoaded value)? cachedQuizzesLoaded,
    TResult Function(TopicsSuccess value)? success,
    TResult Function(TopicsError value)? error,
    TResult Function(TopicsOffline value)? offline,
    required TResult orElse(),
  }) {
    if (offline != null) {
      return offline(this);
    }
    return orElse();
  }
}

abstract class TopicsOffline implements TopicsState {
  const factory TopicsOffline(
      {required final String message,
      final List<Topic>? cachedTopics,
      final List<Quiz>? cachedQuizzes}) = _$TopicsOfflineImpl;

  String get message;
  List<Topic>? get cachedTopics;
  List<Quiz>? get cachedQuizzes;
  @JsonKey(ignore: true)
  _$$TopicsOfflineImplCopyWith<_$TopicsOfflineImpl> get copyWith =>
      throw _privateConstructorUsedError;
}
